//! Catalog readiness: what an installer must do beyond downloading a
//! model's archive before the voice works offline (#92).
//!
//! `g2p_enabled` answers "can this build phonemize the language?"
//! Readiness answers the installer's question: "is this catalog entry
//! verifiable and usable offline, and if not, what stands in the way?"
//! The taxonomy and the per-family audit behind these values live in
//! `SHERPA_CATALOG_AUDIT.md` (generated by
//! `scripts/sherpa-catalog-audit.py`).
//!
//! Precedence: a hard block (no url / no checksum) outranks family
//! asset needs, which outrank "works but unverified". Values are
//! stable strings — downloaders match on the prefix and surface the
//! suffix as the reason (`blocked:no-sha256` → reason "no-sha256").
//! The registry's sha256 fact is passed in explicitly because the
//! public [`SherpaModelInfo`] shape does not carry it.

use crate::types::SherpaModelInfo;

/// Locales with a published (but possibly not yet validated)
/// VoiceGarden bundle — the union of BOTH v0.3.1 manifests, keyed on
/// BCP-47 primary subtags: the base `lexicons.json` (ca cs de en es fa
/// fr it nl pt ru sv sw) plus the expanded `expanded.json` (its
/// corpus-tag keys ara/ben/dan/deu/ell/… map to ar bn da de el … via
/// each entry's `bcp47`). NOT the validated allowlist (that is
/// [`crate::sherpa_lang::LANG_BUNDLES`]); this set distinguishes
/// `blocked:bundle-not-validated` (data exists, validation pending)
/// from `blocked:no-bundle` (no data at all). Sync when
/// voicegarden-lexicons publishes new languages — both manifests.
const PUBLISHED_BUNDLE_LOCALES: &[&str] = &[
    // base manifest
    "ca", "cs", "de", "es", "fa", "fr", "it", "nl", "pt", "ru", "sv", "sw",
    // expanded-only additions (bcp47 primary subtags)
    "ar", "bn", "da", "el", "fi", "he", "hi", "id", "is", "nb", "pl", "ro", "sk", "sl", "ta", "tr",
    "ur",
    // de appears in both; en excluded — English rides the auto-lexicon
];

/// Compute the readiness value for one registry model.
///
/// `has_sha256` and `deprecated` are registry facts the public model
/// shape does not carry (the enrichment forwards them). The G2P facts
/// are computed here: `g2p_enabled_for` (validated allowlist row,
/// build-independent) vs the compiled feature — a validated bundle
/// whose front-end is not in this build gets its own reason instead
/// of masquerading as "no data".
#[must_use]
pub fn readiness_for(model: &SherpaModelInfo, has_sha256: bool, deprecated: bool) -> String {
    if model.url.is_empty() {
        return "blocked:no-url".to_string();
    }
    // MMS: native character/lexicon front-end, no bundle needed — and
    // no sha256 anywhere in the registry (a catalog-repo gap; Dasher
    // installs MMS via its own pinned path). "Works, unverified here"
    // rather than blocked.
    if model.model_type == "mms" {
        return "unverified".to_string();
    }
    // every other family: an unverifiable download blocks install
    if !has_sha256 {
        return "blocked:no-sha256".to_string();
    }
    // deprecated models keep working but should not be offered as new
    // installs (upstream archived / voice builder shut down)
    if deprecated {
        return "blocked:deprecated".to_string();
    }
    match model.model_type.as_str() {
        // bundled front-ends, complete checksummed archives
        "kokoro" | "kitten" | "supertonic" | "pocket" | "floravox-student" => "ready".to_string(),
        // shared vocoder downloads the wrapper resolves at engine
        // level; an installer fetches them alongside the archive
        "matcha" => "needs_assets:vocoder".to_string(),
        "zipvoice" => "needs_assets:vocoder-reference".to_string(),
        // vits family (incl. piper; unknown types ride the vits path)
        _ => vits_readiness(model),
    }
}

fn vits_readiness(model: &SherpaModelInfo) -> String {
    let validated_g2p = crate::sherpa_lang::g2p_enabled_for(model);
    if validated_g2p && cfg!(feature = "sherpa-g2p") {
        // validated VoiceGarden locale (German today): the installer
        // calls tts_provision_sherpa_g2p_bundle after the download
        return "needs_bundle".to_string();
    }
    if validated_g2p {
        // data exists AND is validated — this BUILD lacks the
        // front-end (the sherpa-g2p feature is off). Distinct from
        // "no data": the fix is a rebuild, not new data.
        return "blocked:g2p-unavailable".to_string();
    }
    let Some(first) = model.language.first() else {
        return "blocked:no-language".to_string();
    };
    let lang = first.lang_code.to_ascii_lowercase();
    // Chinese voices ship their own dict/jieba front-end
    if lang.starts_with("zh") || lang == "cantonese" {
        return "ready".to_string();
    }
    if crate::sherpaonnx_engine::is_english_model_id(&model.id.to_ascii_lowercase()) {
        // English: the #66/#67 auto-lexicon path (validated in CI)
        return "ready".to_string();
    }
    // non-English without a validated bundle: a bundle either exists
    // but is not validated yet, or does not exist for the locale
    if PUBLISHED_BUNDLE_LOCALES.contains(&lang.as_str()) {
        "blocked:bundle-not-validated".to_string()
    } else {
        "blocked:no-bundle".to_string()
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::types::SherpaLanguage;

    fn model(id: &str, model_type: &str, lang: &str) -> SherpaModelInfo {
        SherpaModelInfo {
            id: id.to_string(),
            model_type: model_type.to_string(),
            engines: "sherpa-onnx".to_string(),
            name: id.to_string(),
            language: vec![SherpaLanguage {
                lang_code: lang.to_string(),
                language_name: lang.to_string(),
                country: String::new(),
            }],
            sample_rate: 22_050,
            num_speakers: 1,
            quality: String::new(),
            url: "https://example.com/m.tar.bz2".to_string(),
            compression: true,
            filesize_mb: 1.0,
            license: "MIT".to_string(),
            license_url: String::new(),
        }
    }

    #[test]
    fn readiness_covers_the_taxonomy() {
        // blocked:no-url outranks everything (even missing sha)
        let mut m = model("x-vits", "vits", "de");
        m.url = String::new();
        assert_eq!(readiness_for(&m, false, false), "blocked:no-url");

        // mms: unverified even without sha (own install path)
        assert_eq!(
            readiness_for(&model("mms_abp", "mms", "abp"), false, false),
            "unverified"
        );

        // no checksum blocks non-mms families
        assert_eq!(
            readiness_for(&model("piper-de_DE-x", "vits", "de"), false, false),
            "blocked:no-sha256"
        );
        assert_eq!(
            readiness_for(&model("kokoro-x", "kokoro", "en"), false, false),
            "blocked:no-sha256"
        );

        // deprecated outranks family readiness (checksummed but retired)
        assert_eq!(
            readiness_for(&model("supertonic-3", "supertonic", "en"), true, true),
            "blocked:deprecated"
        );

        // checksummed, bundled front-ends
        assert_eq!(
            readiness_for(&model("kokoro-en-v0_19", "kokoro", "en"), true, false),
            "ready"
        );
        // family asset needs
        assert_eq!(
            readiness_for(&model("matcha-en-x", "matcha", "en"), true, false),
            "needs_assets:vocoder"
        );
        assert_eq!(
            readiness_for(&model("zipvoice-x", "zipvoice", "zh"), true, false),
            "needs_assets:vocoder-reference"
        );

        // vits: validated bundle locale. With the feature compiled in
        // → needs_bundle (installer provisions). The thorsten fixture
        // matches the real registry shape.
        let thorsten = model("piper-de_DE-thorsten-medium", "vits", "de");
        if cfg!(feature = "sherpa-g2p") {
            assert_eq!(readiness_for(&thorsten, true, false), "needs_bundle");
        } else {
            // data exists AND is validated — this build lacks the
            // front-end. NOT "no-bundle": the fix is a rebuild.
            assert_eq!(
                readiness_for(&thorsten, true, false),
                "blocked:g2p-unavailable"
            );
        }

        // English piper: auto-lexicon path
        assert_eq!(
            readiness_for(&model("piper-en_US-amy-low", "vits", "en"), true, false),
            "ready"
        );

        // published-but-unvalidated bundle locale — pl HAS an expanded
        // bundle (pol.tar.gz), it is just not validated yet
        assert_eq!(
            readiness_for(
                &model("piper-pl_PL-gosia-medium", "vits", "pl"),
                true,
                false
            ),
            "blocked:bundle-not-validated"
        );
        assert_eq!(
            readiness_for(
                &model("piper-fr_FR-siwis-medium", "vits", "fr"),
                true,
                false
            ),
            "blocked:bundle-not-validated"
        );

        // no bundle for the locale at all (Hungarian: neither manifest)
        assert_eq!(
            readiness_for(&model("piper-hu_HU-x", "vits", "hu"), true, false),
            "blocked:no-bundle"
        );

        // Chinese: own dict front-end
        assert_eq!(
            readiness_for(&model("vits-icefall-zh-x", "vits", "zh"), true, false),
            "ready"
        );
    }

    /// Every value readiness_for can emit, pinned exactly — downloaders
    /// match these strings, so a change is a breaking API change. The
    /// FFI test additionally validates the emitted set over the real
    /// registry.
    #[test]
    fn readiness_emits_exactly_the_documented_values() {
        let expected: &[&str] = &[
            "ready",
            "needs_bundle",
            "needs_assets:vocoder",
            "needs_assets:vocoder-reference",
            "unverified",
            "blocked:no-url",
            "blocked:no-sha256",
            "blocked:deprecated",
            "blocked:g2p-unavailable",
            "blocked:no-language",
            "blocked:bundle-not-validated",
            "blocked:no-bundle",
        ];
        // every branch above is exercised by readiness_covers_the_taxonomy
        // plus the no-language edge; assert each documented value is
        // actually reachable from the fixtures in this module
        let mut seen: Vec<String> = Vec::new();
        for (m, sha, dep) in [
            (model("kokoro-en-v0_19", "kokoro", "en"), true, false),
            (model("piper-de_DE-t", "vits", "de"), true, false),
            (model("matcha-en-x", "matcha", "en"), true, false),
            (model("zipvoice-x", "zipvoice", "zh"), true, false),
            (model("mms_abp", "mms", "abp"), false, false),
            (model("supertonic-3", "supertonic", "en"), true, true),
            (model("piper-pl_PL-g", "vits", "pl"), true, false),
            (model("piper-hu_HU-x", "vits", "hu"), true, false),
        ] {
            let r = readiness_for(&m, sha, dep);
            assert!(
                expected.contains(&r.as_str()),
                "emitted undocumented value {r:?}"
            );
            seen.push(r);
        }
        // the no-language edge: a language-less vits entry
        let mut no_lang = model("vits-none", "vits", "de");
        no_lang.language.clear();
        assert_eq!(readiness_for(&no_lang, true, false), "blocked:no-language");
    }

    /// The published-locale set must cover BOTH voicegarden manifests
    /// (the first version shipped base-only and mislabeled 95 models
    /// as no-bundle; loop-review). Spot-pin the expanded-only locales.
    #[test]
    fn published_locales_cover_both_manifests() {
        for l in ["pl", "ar", "is", "tr", "fi", "da", "el", "hi", "ro", "sk"] {
            assert!(
                PUBLISHED_BUNDLE_LOCALES.contains(&l),
                "expanded-manifest locale {l} missing"
            );
        }
        // and a locale in NEITHER manifest stays no-bundle
        assert!(!PUBLISHED_BUNDLE_LOCALES.contains(&"hu"));
        assert!(!PUBLISHED_BUNDLE_LOCALES.contains(&"zh"));
    }
}
